//! Original LX7 instructions exercise sourced5-inch/4.3B GPIO, RTC, touch, RGB DMA and SD.
//! These are original diagnostics, not manufacturer firmware boot acceptance.
use emu_core::{Bus,Core};
use esp_soc::{SocBus,Stop};
use esp32s3::board;
const PC:u32=0x4037_0000;const GPIO:u32=0x6000_4000;
struct Guest {m:esp32s3::Machine}
impl Guest {
    fn new(name:&str)->Self {let mut m=esp32s3::machine([0;6]);m.bus.board=board::make_board(name).unwrap();m.bus.attach_board_devices();let(f,p)=if name=="waveshare-s3-matrix8"{(4,2)}else if name=="waveshare-s3-geek"{(16,2)}else{(16,8)};m.bus.set_flash_size(f<<20);m.bus.set_psram_size(p<<20).unwrap();m.bus.load_bytes(PC,&[0x32,0x64,0,0x52,0x24,0]).unwrap();m.cores[0].ps=0;m.cores[0].set_jit(false);Self{m}}
    fn put(&mut self,address:u32,value:u32){self.m.cores[0].pc=PC;self.m.cores[0].set_ar(4,address);self.m.cores[0].set_ar(3,value);assert!(matches!(self.m.run(1),Stop::MaxInsns));}
    fn get(&mut self,address:u32)->u32 {self.m.cores[0].pc=PC+3;self.m.cores[0].set_ar(4,address);assert!(matches!(self.m.run(1),Stop::MaxInsns));self.m.cores[0].get_ar(5)}
    fn route(&mut self,pin:u8,signal:u32){self.put(0x6000_9004+4*u32::from(pin),1<<12|1<<9);self.put(GPIO+0x554+4*u32::from(pin),signal);if signal==256{self.put(GPIO+if pin<32{0x24}else{0x30},1<<(pin%32));}}
    fn high(&mut self,pin:u8,value:bool){self.put(GPIO+if pin<32{if value{8}else{12}}else if value{20}else{24},1<<(pin%32));}
    fn i2c_route(&mut self,b:u32,sda:u8,scl:u8){for(p,s)in[(sda,90+b*2),(scl,89+b*2)]{self.route(p,s);self.put(GPIO+0x154+4*s,0x80|u32::from(p));}}
    fn i2c(&mut self,b:u32,address:u8,data:&[u8],n:u8)->Option<Vec<u8>>{
        let base=[0x6001_3000,0x6002_7000][b as usize];self.put(base+0x24,u32::MAX);self.put(base+0x18,3<<12);
        let mut commands=vec![];if !data.is_empty()||n==0{for v in[address<<1].into_iter().chain(data.iter().copied()){self.put(base+0x1c,u32::from(v));}commands.extend([6<<11,1<<11|1<<8|(data.len()+1)as u32]);}
 if n>0{self.put(base+0x1c,u32::from(address<<1|1));commands.extend([6<<11,1<<11|1<<8|1,3<<11|u32::from(n)]);}commands.push(2<<11);
        for(i,c)in commands.into_iter().enumerate(){self.put(base+0x58+4*i as u32,c);}self.put(base+4,1<<5);self.m.bus.tick(100_000);
        if self.get(base+0x20)&(1<<10)!=0{return None;}assert_ne!(self.get(base+0x20)&(1<<7),0);Some((0..n).map(|_|self.get(base+0x1c)as u8).collect())
    }
}

const BOARDS:[(&str,u32,u32,bool);5]=[("waveshare-s3-touch-lcd5",800,480,true),("waveshare-s3-lcd5",800,480,false),("waveshare-s3-touch-lcd5-1024",1024,600,true),("waveshare-s3-lcd5-1024",1024,600,false),("waveshare-s3-touch-lcd43b",800,480,true)];
fn initialize(g:&mut Guest){g.i2c_route(0,8,9);g.route(4,256);g.high(4,false);g.i2c(0,0x24,&[1],0).unwrap();g.i2c(0,0x38,&[0xfd],0).unwrap();g.m.bus.refresh_board_outputs();g.i2c(0,0x38,&[255],0).unwrap();g.m.bus.refresh_board_outputs();}
fn rgb_route(g:&mut Guest){for(p,s)in[(7,154),(5,150),(3,152),(46,151)]{g.route(p,s);}for(i,p)in[14,38,18,17,10,39,0,45,48,47,21,1,2,42,41,40].into_iter().enumerate(){g.route(p,133+i as u32);}}
fn rgb_dma(g:&mut Guest,w:u32,h:u32){const DESC:u32=0x3fc88000;const DATA:u32=0x3fc8a000;let total=w*h*2;let mut data=vec![0;4092];for(i,p)in[(0,0xf800u16),((w*h/2)as usize,0x07e0),((w*h-1)as usize,0x001f)]{let at=(2*i)%4092;data[at..at+2].copy_from_slice(&p.to_le_bytes());}g.m.bus.load_bytes(DATA,&data).unwrap();let(mut pos,mut index)=(0,0);while pos<total{let len=(total-pos).min(4092);let last=pos+len==total;for(i,v)in[1<<31|u32::from(last)<<30|len<<12|len,DATA,if last{0}else{DESC+12*(index+1)}].into_iter().enumerate(){g.put(DESC+12*index+4*i as u32,v);}pos+=len;index+=1;}for(a,v)in[(0x60041014,0),(0x600c001c,1<<8),(0x6003f0a8,5),(0x6003f080,(DESC&0xfffff)|(1<<21)),(0x60041000,(1<<31)|(3<<29)|(20<<9)|(1<<6)),(0x60041020,((w-1)<<8)|((w+21)<<20)),(0x6004101c,(1<<31)|((h-1)<<11)|((h+38)<<21)),(0x60041014,(1<<27)|(1<<24)|(1<<23))]{g.put(a,v);}for _ in 0..240{g.m.bus.tick(100_000);}g.m.bus.refresh_board_outputs();}
#[test]fn actual_lx7_rgb_dma_distinguishes_two_resolutions_and_populated_ex3_reset(){for(name,w,h,_)in BOARDS{let mut g=Guest::new(name);initialize(&mut g);rgb_route(&mut g);rgb_dma(&mut g,w,h);let f=g.m.bus.board.display().unwrap();assert_eq!((f.0,f.1),(w,h));assert_eq!([f.2[0],f.2[(w*h/2)as usize],f.2[(w*h-1)as usize]],[0xf800,0x07e0,0x001f],"{name} {} geometry={:?} socframes={}",g.m.bus.board.report(),g.m.bus.periph.lcd_cam.lcd_geometry(),g.m.bus.periph.lcd_cam.lcd_frames);let frames=g.m.bus.board.display_frames();g.route(14,132);rgb_dma(&mut g,w,h);assert_eq!(g.m.bus.board.display_frames(),frames);rgb_route(&mut g);g.i2c(0,0x38,&[0xf7],0).unwrap();g.m.bus.refresh_board_outputs();rgb_dma(&mut g,w,h);assert_eq!(g.m.bus.board.display_frames(),frames);assert!(g.m.bus.board.display().unwrap().2.iter().all(|&x|x==0));g.i2c(0,0x38,&[255],0).unwrap();g.m.bus.refresh_board_outputs();assert!(g.m.bus.board.display().unwrap().2.iter().all(|&x|x==0),"reset release needs a fresh DMA frame");rgb_dma(&mut g,w,h);assert_eq!(g.m.bus.board.display().unwrap().2[0],0xf800);g.i2c(0,0x38,&[0xfb],0).unwrap();assert!(g.m.bus.board.display().unwrap().2.iter().all(|&x|x==0),"independent EX2 backlight");}}
#[test]fn actual_lx7_touch_coordinates_follow_exact_glass_and_non_touch_has_no_controller(){for(name,w,h,touch)in BOARDS{let mut g=Guest::new(name);initialize(&mut g);assert!(g.i2c(0,0x14,&[0x81,0x40],1).is_none(),"IRQ low selected5D");if !touch{assert!(g.i2c(0,0x5d,&[0x81,0x40],1).is_none());continue;}g.i2c(0,0x5d,&[0x81,0x4e,0],0).unwrap();g.m.bus.board.touch((w-1)as u16,(h-1)as u16,true);g.m.bus.tick(2_500_000);g.m.bus.board.advance_to(g.m.bus.cycles);let r=g.i2c(0,0x5d,&[0x81,0x4e],6).unwrap();assert_eq!(&r[..2],&[0x81,0]);assert_eq!(u16::from_le_bytes([r[2],r[3]]),w as u16-1);assert_eq!(u16::from_le_bytes([r[4],r[5]]),h as u16-1);g.i2c(0,0x38,&[0xfd],0).unwrap();g.m.bus.refresh_board_outputs();assert!(g.i2c(0,0x5d,&[0x81,0x4e],1).is_none());g.i2c_route(0,9,8);assert!(g.i2c(0,0x38,&[255],0).is_none());}}
#[test]fn actual_lx7_pcf85063_calendar_has_guest_time_stop_and_no_legacy_board_alias(){for(name,_,_,_)in BOARDS{let mut g=Guest::new(name);initialize(&mut g);g.i2c(0,0x51,&[4,0x58,0x59,0x23,0x28,3,2,0x24],0).unwrap();g.m.bus.tick(480_000_000);g.m.bus.board.advance_to(g.m.bus.cycles);assert_eq!(g.i2c(0,0x51,&[4],7),Some(vec![0,0,0,0x29,4,2,0x24]));g.i2c(0,0x51,&[0,0x20],0).unwrap();let before=g.i2c(0,0x51,&[4],7);g.m.bus.tick(480_000_000);g.m.bus.board.advance_to(g.m.bus.cycles);assert_eq!(g.i2c(0,0x51,&[4],7),before);g.i2c_route(0,15,7);assert!(g.i2c(0,0x51,&[4],1).is_none());}for name in["waveshare-s3-touch-lcd7","waveshare-s3-touch-lcd43"]{let mut g=Guest::new(name);g.i2c_route(0,8,9);assert!(g.i2c(0,0x51,&[4],1).is_none());}}
fn spi_mmio(g:&mut Guest,tx:&[u8],read:usize)->Vec<u8>{let base=0x6002_5000;let mut reply=Vec::new();let total=if read>0{read}else{tx.len()};for start in(0..total).step_by(64){let n=(total-start).min(64);g.put(base+0x10,if read>0{1<<28}else{1<<27});g.put(base+0x1c,n as u32*8-1);if read==0{for(i,c)in tx[start..start+n].chunks(4).enumerate(){g.put(base+0x98+4*i as u32,c.iter().enumerate().fold(0,|v,(j,b)|v|u32::from(*b)<<(8*j)));}}g.put(base,1<<24);g.m.bus.flush_ticks();if read>0{for i in(0..n).step_by(4){let w=g.get(base+0x98+i as u32).to_le_bytes();reply.extend_from_slice(&w[..(n-i).min(4)]);}}}reply}
fn sd_command(g:&mut Guest,c:u8,arg:u32)->Vec<u8>{let mut bytes=vec![0x40|c];bytes.extend(arg.to_be_bytes());bytes.push(if c==0{0x95}else if c==8{0x87}else{255});spi_mmio(g,&bytes,0);spi_mmio(g,&[],2)}
#[test]fn actual_lx7_spi_tf_sector_write_read_and_wrong_miso_for_all_five_large_panel_profiles(){for(name,clk,mosi,miso,cs)in BOARDS.map(|(name,_,_,_)|(name,12,11,13,None::<u8>)){
 let mut g=Guest::new(name);g.m.bus.board.attach_spi_sd_card(Box::new(esp_periph::sdmmc::MemStore(vec![0;1<<20])),Default::default()).unwrap();for(p,s)in[(clk,66),(mosi,68)]{g.route(p,s);}g.route(miso,256);g.put(GPIO+0x154+4*67,0x80|u32::from(miso));g.put(0x6002_5000+0x20,0x3f);
 if let Some(pin)=cs{g.route(pin,256);g.high(pin,true);}else{g.i2c_route(0,8,9);g.i2c(0,0x24,&[1],0).unwrap();g.i2c(0,0x38,&[255],0).unwrap();if name=="waveshare-s3-lcd5"||name=="waveshare-s3-lcd5-1024"{assert!(g.i2c(0,0x5d,&[],1).is_none());assert!(g.i2c(0,0x14,&[],1).is_none());assert!(g.i2c(0,0x51,&[4],1).is_some());}}
 spi_mmio(&mut g,&[255;10],0);if let Some(pin)=cs{g.high(pin,false);}else{g.i2c(0,0x38,&[0xef],0).unwrap();}assert_eq!(sd_command(&mut g,0,0),[255,1],"{name}");assert_eq!(sd_command(&mut g,8,0x1aa),[255,1]);assert_eq!(spi_mmio(&mut g,&[],4),[0,0,1,0xaa]);for _ in 0..2{assert_eq!(sd_command(&mut g,55,0),[255,1]);sd_command(&mut g,41,1<<30);}assert_eq!(sd_command(&mut g,24,3),[255,0]);let mut bytes=vec![0xfe];let sector=(0..512).map(|x|(x as u8).wrapping_mul(37)).collect::<Vec<_>>();bytes.extend(&sector);bytes.extend([255,255]);spi_mmio(&mut g,&bytes,0);assert_eq!(spi_mmio(&mut g,&[],1),[5]);assert_eq!(sd_command(&mut g,17,3),[255,0]);assert_eq!(spi_mmio(&mut g,&[],2),[255,0xfe]);assert_eq!(spi_mmio(&mut g,&[],512),sector);spi_mmio(&mut g,&[],2);g.put(GPIO+0x154+4*67,0x80|if miso==37{13}else{37});assert_eq!(sd_command(&mut g,0,0),[255,255]);g.m.bus.board.set_sd_card_present(false);g.put(GPIO+0x154+4*67,0x80|u32::from(miso));assert_eq!(sd_command(&mut g,0,0),[255,255]);assert!(g.m.bus.board.sd_card_slot().is_none());
}}
